export const getListHousekeepingTasksUrl = (propertySlug: string,
    params?: ListHousekeepingTasksParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/properties/${propertySlug}/housekeeping/tasks?${stringifiedParams}` : `/api/properties/${propertySlug}/housekeeping/tasks`
}

